      "publishedNodesJson": "[{\"id\":\"accepted-start\",\"type\":\"player-choice\",\"speakerName\":\"\",\"characterId\":\"\",\"text\":\"\",\"nextNodeId\":\"\",\"options\":[{\"label\":\"把彩虹豆豆跳跳糖递给西格莉卡\",\"nextNodeId\":\"accepted-admire\"}]},{\"id\":\"accepted-admire\",\"type\":\"story\",\"speakerName\":\"西格莉卡\",\"characterId\":\"sigrika\",\"text\":\"哇，好漂亮的糖！这些颜色像揉在一起的星光一样。\",\"nextNodeId\":\"accepted-agree\",\"options\":[{\"label\":\"要尝一颗吗？\",\"nextNodeId\":\"accepted-agree\"}]},{\"id\":\"accepted-agree\",\"type\":\"story\",\"speakerName\":\"西格莉卡\",\"characterId\":\"sigrika\",\"text\":\"嗯！闻起来甜甜的，那我就不客气啦。\",\"nextNodeId\":\"accepted-eat\",\"options\":[]},{\"id\":\"accepted-eat\",\"type\":\"story\",\"speakerName\":\"\",\"characterId\":\"\",\"text\":\"西格莉卡把糖果放进口中，开心地嚼了几下。\",\"nextNodeId\":\"accepted-taste\",\"options\":[]},{\"id\":\"accepted-taste\",\"type\":\"story\",\"speakerName\":\"西格莉卡\",\"characterId\":\"sigrika\",\"text\":\"唔，味道还不错——嗝！\",\"nextNodeId\":\"accepted-hiccup\",\"options\":[]},{\"id\":\"accepted-hiccup\",\"type\":\"story\",\"speakerName\":\"西格莉卡\",\"characterId\":\"sigrika\",\"text\":\"诶？嗝！怎么回......嗝！为什么嗝不下来呀！\",\"nextNodeId\":\"accepted-doctor\",\"options\":[{\"label\":\"你还好吗？\",\"nextNodeId\":\"accepted-doctor\"}]},{\"id\":\"accepted-doctor\",\"type\":\"story\",\"speakerName\":\"西格莉卡\",\"characterId\":\"sigrika\",\"text\":\"我、嗝没事！嗝！我先去找嗝医生看看！\",\"nextNodeId\":\"accepted-runs\",\"options\":[]},{\"id\":\"accepted-runs\",\"type\":\"story\",\"speakerName\":\"\",\"characterId\":\"\",\"text\":\"西格莉卡红着脸跑远了。等你抬头想叫住她时，她早已不见踪影。\",\"nextNodeId\":\"accepted-unavailable\",\"options\":[]},{\"id\":\"accepted-unavailable\",\"type\":\"story\",\"speakerName\":\"\",\"characterId\":\"\",\"text\":\"看来暂时不能找她下棋了。\",\"nextNodeId\":\"\",\"options\":[]},{\"id\":\"rejected-start\",\"type\":\"player-choice\",\"speakerName\":\"\",\"characterId\":\"\",\"text\":\"\",\"nextNodeId\":\"\",\"options\":[{\"label\":\"把彩虹豆豆跳跳糖递给西格莉卡\",\"nextNodeId\":\"rejected-admire\"}]},{\"id\":\"rejected-admire\",\"type\":\"story\",\"speakerName\":\"西格莉卡\",\"characterId\":\"sigrika\",\"text\":\"哇，好漂亮的糖！是给我的吗？\",\"nextNodeId\":\"rejected-check\",\"options\":[]},{\"id\":\"rejected-check\",\"type\":\"story\",\"speakerName\":\"西格莉卡\",\"characterId\":\"sigrika\",\"text\":\"……等等，这个包装上怎么连生产日期都没有？\",\"nextNodeId\":\"rejected-refuse\",\"options\":[{\"label\":\"吃一颗应该没关系吧？\",\"nextNodeId\":\"rejected-refuse\"}]},{\"id\":\"rejected-refuse\",\"type\":\"story\",\"speakerName\":\"西格莉卡\",\"characterId\":\"sigrika\",\"text\":\"不行不行！我今天还要陪大家下棋呢，万一又出现什么奇怪的副作用就糟了。\",\"nextNodeId\":\"rejected-doctor\",\"options\":[]},{\"id\":\"rejected-doctor\",\"type\":\"story\",\"speakerName\":\"西格莉卡\",\"characterId\":\"sigrika\",\"text\":\"等陆医生检查过再说吧。放心，如果确认没问题，我会认真考虑吃一颗的！\",\"nextNodeId\":\"rejected-return\",\"options\":[]},{\"id\":\"rejected-return\",\"type\":\"story\",\"speakerName\":\"\",\"characterId\":\"\",\"text\":\"西格莉卡把糖果推了回来。看来今天没办法得逞了。\",\"nextNodeId\":\"\",\"options\":[]}]",
